steps.in:
cat > memlog.sh <<'EOF'
#!/usr/bin/env bash
# Logs laptop memory once a minute until END (epoch seconds), then exits.
# Columns are MiB unless named otherwise. Group columns are RSS+swap summed over processes
# (RSS double-counts shared pages a little; good enough for build sizing).
set -u
out=${1:?csv path}
end=${2:?end epoch}
[[ -s $out ]] || echo "time,mem_total,mem_avail,mem_used,swap_used,psi_some60,psi_full60,load1,claude_n,claude_mb,cargo_n,rustc_n,rust_mb,java_n,java_mb,brave_mb,other_mb" > "$out"
while (( $(date +%s) < end )); do
  awk '/^MemTotal/{t=$2}/^MemAvailable/{a=$2}/^SwapTotal/{st=$2}/^SwapFree/{sf=$2}
       END{printf "%d,%d,%d,%d,", t/1024, a/1024, (t-a)/1024, (st-sf)/1024}' /proc/meminfo > /tmp/.memlog.$$ 2>/dev/null || true
  line="$(date +%FT%T),$(cat /tmp/.memlog.$$)"
  psi=$(awk '/^some/{split($3,a,"=");s=a[2]}/^full/{split($3,b,"=");f=b[2]}END{print s","f}' /proc/pressure/memory)
  load=$(cut -d' ' -f1 /proc/loadavg)
  groups=$(for d in /proc/[0-9]*; do
      awk 'BEGIN{n="";r=0;s=0}/^Name:/{n=$2}/^VmRSS:/{r=$2}/^VmSwap:/{s=$2}END{if(n!="")print n, r+s}' "$d/status" 2>/dev/null
    done | awk '
      {kb=$2; n=$1}
      n=="claude"{cn++; cm+=kb; next}
      n=="cargo"{gn++; rm+=kb; next}
      n=="rustc"{rn++; rm+=kb; next}
      n ~ /^(cc|cc1|cc1plus|ld|ld.lld|mold|lld|clang|build-script-b|build_script_b)/{rm+=kb; next}
      n=="java"{jn++; jm+=kb; next}
      n ~ /^brave/{bm+=kb; next}
      {om+=kb}
      END{printf "%d,%d,%d,%d,%d,%d,%d,%d,%d", cn, cm/1024, gn, rn, rm/1024, jn, jm/1024, bm/1024, om/1024}')
  echo "$line$psi,$load,$groups" >> "$out"
  sleep 60
done
rm -f /tmp/.memlog.$$
EOF
chmod +x memlog.sh
end=$(( $(date +%s) + 86400 )); echo "end $(date -d @$end)"
systemd-run --user --unit=dibs-memlog --description="Task 33: log memory every minute for 24h" "$PWD/memlog.sh" "$PWD/memlog.csv" "$end"
sleep 3; cat memlog.csv; systemctl --user status dibs-memlog --no-pager | head -5

